:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --accent: #e94560;
  --accent-light: #ff6b6b;
  --text: #eaeaea;
  --text-muted: #a0a0b0;
  --bar: #0f3460;
  --bar-highlight: #e94560;
  --input-bg: #0f3460;
  --border: #2a2a4a;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] { display: none !important; }

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
}

.card {
  background: var(--card-bg);
  border-radius: 16px;
  padding: 32px 24px;
  max-width: 640px;
  width: 100%;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  border: 1px solid var(--border);
}

header {
  text-align: center;
  margin-bottom: 24px;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--accent-light);
  margin-bottom: 8px;
}

.subtitle {
  color: var(--text-muted);
  font-size: 1rem;
}

.inputs {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 8px;
  margin-bottom: 24px;
}

.input-group {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.input-group label {
  font-size: 0.875rem;
  color: var(--text-muted);
  font-weight: 600;
}

.input-group input {
  width: 100%;
  min-width: 0;
  padding: 10px 4px;
  font-size: 1rem;
  text-align: center;
  background: var(--input-bg);
  border: 2px solid var(--border);
  border-radius: 8px;
  color: var(--text);
  transition: border-color 0.2s, box-shadow 0.2s;
}

.input-group input:hover {
  border-color: var(--accent-light);
}

.input-group input:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(233, 69, 96, 0.3);
}

.input-group input:active {
  background: #1a1a3e;
}

.chart-section {
  background: var(--bg);
  border-radius: 12px;
  padding: 16px;
  margin-bottom: 24px;
  border: 1px solid var(--border);
}

canvas {
  display: block;
  width: 100%;
  height: auto;
  image-rendering: pixelated;
}

.summary {
  text-align: center;
  font-size: 1.125rem;
  line-height: 1.6;
}

.summary p {
  margin-bottom: 8px;
}

.summary strong {
  color: var(--accent-light);
  font-size: 1.25rem;
}

.highlight {
  color: var(--accent);
  font-weight: 700;
}

@media (max-width: 480px) {
  .card {
    padding: 24px 16px;
  }
  .inputs {
    grid-template-columns: repeat(4, 1fr);
  }
  .input-group:nth-child(5),
  .input-group:nth-child(6),
  .input-group:nth-child(7) {
    grid-column: span 1;
  }
}

@media (max-width: 360px) {
  .inputs {
    grid-template-columns: repeat(3, 1fr);
  }
  h1 {
    font-size: 1.5rem;
  }
}

const DAYS = ['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun'];
const DAY_LABELS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
const MAX_HOURS = 12;

const canvas = document.getElementById('chart');
const ctx = canvas.getContext('2d');
const averageEl = document.getElementById('average');
const longestEl = document.getElementById('longest-night');

const inputs = {};
DAYS.forEach(id => {
  inputs[id] = document.getElementById(id);
});

function getValues() {
  return DAYS.map(id => {
    const val = parseFloat(inputs[id].value);
    return isNaN(val) ? 0 : Math.min(MAX_HOURS, Math.max(0, val));
  });
}

function drawChart(values) {
  const dpr = window.devicePixelRatio || 1;
  const rect = canvas.getBoundingClientRect();
  const cssWidth = rect.width || 560;
  const cssHeight = 300;

  canvas.width = cssWidth * dpr;
  canvas.height = cssHeight * dpr;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

  const w = cssWidth;
  const h = cssHeight;
  ctx.clearRect(0, 0, w, h);

  const padding = { top: 20, right: 20, bottom: 40, left: 40 };
  const chartW = w - padding.left - padding.right;
  const chartH = h - padding.top - padding.bottom;

  const maxVal = Math.max(...values, 1);
  const maxNightIndex = values.indexOf(Math.max(...values));

  // Draw grid lines and y-axis labels
  ctx.strokeStyle = '#2a2a4a';
  ctx.lineWidth = 1;
  ctx.fillStyle = '#a0a0b0';
  ctx.font = '12px system-ui, sans-serif';
  ctx.textAlign = 'right';
  ctx.textBaseline = 'middle';

  const steps = 4;
  for (let i = 0; i <= steps; i++) {
    const val = (maxVal / steps) * i;
    const y = padding.top + chartH - (val / maxVal) * chartH;
    ctx.beginPath();
    ctx.moveTo(padding.left, y);
    ctx.lineTo(w - padding.right, y);
    ctx.stroke();
    ctx.fillText(Math.round(val), padding.left - 8, y);
  }

  // Draw bars
  const barWidth = chartW / values.length;
  const gap = Math.min(8, barWidth * 0.15);
  const actualBarWidth = barWidth - gap;

  values.forEach((val, i) => {
    const x = padding.left + i * barWidth + gap / 2;
    const barH = (val / maxVal) * chartH;
    const y = padding.top + chartH - barH;

    const isLongest = i === maxNightIndex && val > 0;
    ctx.fillStyle = isLongest ? '#e94560' : '#0f3460';
    ctx.fillRect(x, y, actualBarWidth, barH);

    if (isLongest) {
      ctx.strokeStyle = '#ff6b6b';
      ctx.lineWidth = 2;
      ctx.strokeRect(x, y, actualBarWidth, barH);
    }

    // Day label
    ctx.fillStyle = '#a0a0b0';
    ctx.font = '12px system-ui, sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'top';
    ctx.fillText(DAY_LABELS[i], x + actualBarWidth / 2, padding.top + chartH + 8);

    // Value label on top of bar
    if (val > 0) {
      ctx.fillStyle = '#eaeaea';
      ctx.font = 'bold 12px system-ui, sans-serif';
      ctx.textBaseline = 'bottom';
      ctx.fillText(val, x + actualBarWidth / 2, y - 4);
    }
  });
}

function update() {
  const values = getValues();
  const sum = values.reduce((a, b) => a + b, 0);
  const avg = sum / values.length;
  averageEl.textContent = avg.toFixed(1);

  const maxVal = Math.max(...values);
  if (maxVal > 0) {
    const maxIndex = values.indexOf(maxVal);
    longestEl.textContent = `Longest night: ${DAY_LABELS[maxIndex]} (${maxVal} h)`;
  } else {
    longestEl.textContent = 'Longest night: —';
  }

  drawChart(values);
}

DAYS.forEach(id => {
  inputs[id].addEventListener('input', update);
  inputs[id].addEventListener('change', update);
});

window.addEventListener('resize', update);

// Initial render
update();
